using System;using System.Collections.Generic;
namespace RunnersZ.Logic { public enum Difficulty{Easy,Normal,Hard} public sealed class PhraseBank { readonly Random random; readonly Dictionary<Difficulty,string[]> data=new(){[Difficulty.Easy]=new[]{"RUN FAST","OPEN THE DOOR","FIND THE KEY","SAVE THE TEAM","HOLD THE LINE"},[Difficulty.Normal]=new[]{"ATTACK AT DAWN","MEET BEHIND THE TOWER","PROTECT THE MAGIC BOOK","FOLLOW THE BLUE PATH","RETURN TO THE CASTLE"},[Difficulty.Hard]=new[]{"THE BRAVE RUNNER OPENS THE HIDDEN GATE","THE TEAM MUST PROTECT THE ANCIENT LIBRARY","USE THE SECRET PASSAGE BEFORE NIGHT FALLS","THE FINAL MESSAGE REVEALS THE SAFE ROUTE","COURAGE WILL GUIDE US THROUGH THE DARK FOREST"}}; public PhraseBank(int seed){random=new Random(seed);} public string Next(Difficulty d)=>data[d][random.Next(data[d].Length)]; public IReadOnlyList<string> All(Difficulty d)=>data[d];}}